class Box(Flowable):
    def __init__(self, w=5.7*inch, h=2.0*inch, label='IMAGE TO BE INSERTED'):
        super().__init__(); self.width=w; self.height=h; self.label=label
    def draw(self):
        c=self.canv; c.setStrokeColor(colors.black); c.setDash(4,3); c.rect(0,0,self.width,self.height,stroke=1,fill=0); c.setDash()
        c.setFont(ITALIC,12); c.drawCentredString(self.width/2,self.height/2+7,self.label)
        c.setFont(FONT,10); c.drawCentredString(self.width/2,self.height/2-11,'Reserved space for project image')

def logo(path, w, h, label):
    return Image(str(path), width=w, height=h) if Path(path).exists() else Box(w,h,label)

def header_footer(c, doc):
    c.saveState(); n=c.getPageNumber()
    # Preliminary pages remain unnumbered. Printed numbering begins on the
    # standalone Chapter 1 introduction page, matching the signed sample.
    chapter_start_physical_page = 9
    if n >= chapter_start_physical_page:
        c.setFont(FONT,10); c.drawCentredString(W/2,.25*inch,str(n - chapter_start_physical_page + 1))
    c.restoreState()

