page(CH('BONAFIDE CERTIFICATE'), P('This is to certify that the project report entitled <b>"Zero-Knowledge Document Verification Platform"</b> is a record of the project work carried out by <b>P Sakthi Sabareesh</b>, Register Number <b>310625104625</b>, of the Department of Computer Science and Engineering, Easwari Engineering College, during the academic year 2026 - 2027, under the supervision of Ms. A. Bhagyalakshmi, Assistant Professor, Department of Computer Science and Engineering.'), Spacer(1,.35*inch), Table([[P('__________________________','center14'),P('__________________________','center14')],[P('Ms. A. Bhagyalakshmi','center14'),P('Cloudin','center14')],[P('Supervisor\nAssistant Professor, CSE','center14'),P('Head of the Department\nCSE','center14')],[P('\nSignature / Seal','center14'),P('\nSignature / Seal','center14')]],colWidths=[2.8*inch,2.8*inch],style=TableStyle([('ALIGN',(0,0),(-1,-1),'CENTER'),('VALIGN',(0,0),(-1,-1),'TOP'),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),7)])), Spacer(1,.35*inch), P('Internal Examiner: ____________________    External Examiner: ____________________','left14'), P('Submitted for the project work examination held on: ____________________','left14'))
page(CH('DECLARATION'), P('I hereby declare that the project report entitled <b>"Zero-Knowledge Document Verification Platform"</b> is prepared as part of the academic project work carried out by me under the guidance of Ms. A. Bhagyalakshmi, Assistant Professor, Department of Computer Science and Engineering, Easwari Engineering College.'), P('The report documents the actual project repository, including its Java and Spring Boot backend modules, React and TypeScript frontend, cryptographic services, database migrations, security controls, tests and deployment configuration. The implementation details are presented for academic evaluation and are not supplemented with unrelated project features.'), Spacer(1,.45*inch), P('Place: Chennai','left14'), P('Date: ____________________','left14'), Spacer(1,.45*inch), P('Signature of the Student: ______________________________','left14'), P('P Sakthi Sabareesh','left14'))
page(CH('ABSTRACT'), P('Digital documents and credentials are commonly shared to prove qualifications, identity-related attributes and eligibility. Conventional verification often requires the holder to disclose an entire document even when the verifier needs only one fact. This creates unnecessary exposure of personal information and increases the risk of document tampering, forged credentials, uncontrolled copying and weak auditability.'), P('The Zero-Knowledge Document Verification Platform is a Java-based modular application with a React web interface. It combines SHA-256 streaming document digests, RSA-PSS digital signatures, canonical credential encoding, Pedersen commitments and Bulletproof predicate proofs. A holder can prove a supported threshold statement about a committed attribute without revealing the underlying attribute value to the verifier.'), P('The platform separates four roles: issuer, holder, verifier and administrator. Issuers register documents and issue credentials. Holders manage credentials and generate proofs. Verifiers validate public capability tokens, document integrity, credential signatures and predicate statements. Administrators manage key lifecycle records, audit events and recovery checks.'), P('The project uses Java 21, Spring Boot, JDBC, Flyway, PostgreSQL for production, SQLite for local development, React, TypeScript, Vite, Tailwind CSS, Docker and GitHub Actions. The final system is designed for academic demonstration and controlled pilot deployment, with explicit limitations around external identity providers, key custody, artifact durability and production operations.'), P('<b>Keywords:</b> Zero-Knowledge Proofs, Pedersen Commitment, Bulletproofs, RSA-PSS, SHA-256, Credential Verification, Privacy, Document Integrity.'))
